225	  actor: Actor,
226	  input: MoveIssueInput,
227	): Promise<Issue> {
228	  return changeIssueStatus(actor, {
229	    orgId: input.orgId,
230	    issueId: input.issueId,
231	    status: input.toStatus,
232	  });
233	}
