235	export async function getIssue(
236	  actor: Actor,
237	  orgId: OrgId,
238	  issueId: IssueId,
239	): Promise<IssueWithRelations> {
240	  assertOrgScope(actor, orgId);
241	
242	  const issue = requireFound(
243	    await issueRepo.findIssueById(orgId, issueId),
244	    "Issue",
245	    issueId,
246	  );
247	  assertCan(actor, "issue:read", issueResource(issue));
248	
249	  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);
