/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones; a project's
 * `issueNumberWatermark` is folded in too, so a number retired by a move away
 * is never reissued even though the row that carried it is gone.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();

  const project = getDb()
    .select({ watermark: projects.issueNumberWatermark })
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();

  return Math.max(row?.value ?? 0, project?.watermark ?? 0) + 1;
}

