export async function relocateIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
  number: number,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ projectId, number, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

