/**
 * Moves an issue to another project of the same workspace (ADR 0011). Gated
 * on both `issue:update` (editing the issue) and `issue:create` on the
 * target project (the permission and quota a new issue there would need);
 * either refusal leaves the issue untouched. A move within the same project
 * is a no-op: nothing changes, nothing publishes. Otherwise the issue is
 * re-pointed at the target project and given its next number there — the old
 * number is retired and never reissued in the source project — and exactly
 * one `issue.moved` event is published, naming both projects and numbers.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (issue.projectId === input.toProjectId) {
    return issue;
  }

  const targetProject = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", targetProject.id, targetProject);
  assertCan(actor, "issue:create", projectResource(targetProject));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.toProjectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${targetProject.key}`,
    );
  }

  const fromProjectId = issue.projectId;
  const fromNumber = issue.number;
  const toNumber = await issueRepo.nextIssueNumber(
    input.orgId,
    input.toProjectId,
  );

  const moved = await issueRepo.relocateIssueToProject(
    input.orgId,
    input.issueId,
    input.toProjectId,
    toNumber,
  );
  await projectRepo.bumpIssueNumberWatermark(
    input.orgId,
    input.toProjectId,
    toNumber,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: moved.id,
    fromProjectId,
    toProjectId: moved.projectId,
    fromNumber,
    toNumber: moved.number,
  });

  return moved;
}

